const btn=(text,act,id='',cls='')=>`<button type="button" class="${cls}" data-act="${act}" ${act==='ai-draft'&&!aiReady?'disabled title="AI 연결 설정이 필요해요."':''} ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const field=(name,title,value='',type='text',extra='')=>`<label>${title}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const card=(title,body,action='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${action}</div><div class="card-body">${body}</div></section>`;
